// Simple keyword search in PDF text
const question = $json.body?.question?.toLowerCase() || "";
const pdfText = $json.text?.toLowerCase() || "";

if (!question) {
  return [{ answer: "Please provide a question." }];
}

// Split text into sentences
const sentences = pdfText.split(/(?<=\.)/);

// Use the first word of the question to find matches
const results = sentences.filter(s => s.includes(question.split(" ")[0]));

// Return the top 3 matching sentences
const answer = results.slice(0, 3).join(" ") || "Sorry, I couldn’t find that in the PDF.";

return [{ data: $json["answer"] }];

// Function to format the date/time string to a specific timezone (e.g., your local time)
function formatCurrentDate(timeZone) {
  const options = {
    month: 'short', // Nov
    day: '2-digit', // 21
    hour: '2-digit', // 12
    minute: '2-digit', // 26
    second: '2-digit', // 48
    hourCycle: 'h23', // Ensures 24-hour format
    timeZone: timeZone // Applies the desired timezone
  };

  // Get the current date and format it directly using the target timezone
  // The 'en-US' locale helps ensure the format is readable before cleanup
  const d = new Date().toLocaleString('en-US', options);

  // Clean up the string (e.g., remove comma and any potential AM/PM)
  return d.replace(',', '').replace(/\s(AM|PM)$/i, '').trim();
}

// *** IMPORTANT: Timezone updated to Cairo's identifier ***
const TARGET_TIMEZONE = 'Africa/Cairo'; 

const formattedDateString = formatCurrentDate(TARGET_TIMEZONE);

return $input.all().map(item => ({
  json: {
    // Document content
    text: `${item.json.Question}\n\n${item.json.Answer}`,

    metadata: {
      // All data must be passed as raw strings to survive Pinecone
      id: item.json.ID,
      question: item.json.Question,
      answer: item.json.Answer,
      category: item.json.Category,
      frequency: item.json.Frequency,
      tags: item.json.Tags,

      // **Assign the pure, timezoned string**
      lastUpdated: formattedDateString, 
    },
  },
}));

