for (const item of $input.all()) {
  delete item.json.password;
  delete item.json._id;

  const created = item.json.createdAt || item.json.updatedAt;

  delete item.json.createdAt;
  delete item.json.updatedAt;

  const roleNum = Number(item.json.role);
  if (roleNum === 1) {
    item.json.role = 'Admin';
  } else if (roleNum === 2) {
    item.json.role = 'HR';
  } else if (roleNum === 3) {
    item.json.role = 'IT';
  } else {
    item.json.role = 'Other';
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return dateStr;
    const day = String(date.getDate()).padStart(2, '0');
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const month = months[date.getMonth()];
    const year = date.getFullYear();
    return `${day}/${month}/${year}`;
  }

  item.json['joined at'] = formatDate(created);
}
return $input.all();

const rawItems = $input.all();

// Sort by login_time descending (newest first)
rawItems.sort((a, b) => {
  const dateA = a.json.login_time ? new Date(a.json.login_time) : new Date(0);
  const dateB = b.json.login_time ? new Date(b.json.login_time) : new Date(0);
  return dateB - dateA;
});

const formattedLogs = [];
for (const item of rawItems) {
  const log = item.json;

  const employeeId = log.employee_id || '—';
  const name = log.name || '—';
  const email = log.email || '—';

  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return dateStr;
    const day = String(date.getDate()).padStart(2, '0');
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const month = months[date.getMonth()];
    const year = date.getFullYear();
    let hours = date.getHours();
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;
    const timeStr = String(hours).padStart(2, '0') + ':' + minutes + ' ' + ampm;
    return `${day} ${month}, ${year} ${timeStr}`;
  }

  const signInTime = formatDateTime(log.login_time);
  const signOutTime = log.logout_time ? formatDateTime(log.logout_time) : 'Active Now';

  let workDuration = 'Active Now';
  if (log.logout_time) {
    const mins = log.duration_minutes;
    if (mins !== undefined && mins !== null) {
      if (mins < 1) {
        workDuration = '< 1 min';
      } else {
        const hrs = Math.floor(mins / 60);
        const remainingMins = Math.round(mins % 60);
        workDuration = hrs > 0 ? `${hrs} hr ${remainingMins} min` : `${remainingMins} min`;
      }
    } else {
      workDuration = '—';
    }
  }

  formattedLogs.push({
    json: {
      'Employee ID': employeeId,
      'Employee Name': name,
      'Email Address': email,
      'Sign In Time': signInTime,
      'Sign Out Time': signOutTime,
      'Work Duration': workDuration
    }
  });
}

return formattedLogs;
